import {WebSocket} from 'ws';
import * as publicApi from './index.js';
import {createHalEngine} from './config.js';
import type {HalEngine, HalEngineConfig} from './config.js';
import {InMemorySessionStore} from './infrastructure/stores/inMemorySessionStore.js';
import {MongoSessionStore} from './infrastructure/stores/mongo/mongoSessionStore.js';
import type {CollectionLike} from './infrastructure/stores/mongo/mongoDriverTypes.js';
import type {MongoSessionDocument} from './infrastructure/stores/mongo/mongoSessionDocument.js';
import {setLogger} from './shared/logger.js';
import type {Logger} from './shared/logger.js';
import {HAL_WS_SUBPROTOCOL} from './transport/ws/subprotocol.js';
import {validateMessage} from './transport/ws/validation.js';
import type {ValidationResult} from './transport/ws/validation.js';
import {deferred} from './transport/wsTestSupport.js';
import type {WsAuthenticator} from './types/auth.js';
import type {SessionListOptions, SessionStore} from './types/sessionStore.js';

interface RecordedListCall {
  userId: string | number;
  limit: number | undefined;
  before: unknown;
}

interface WireConversationRow {
  sessionId: unknown;
  createdAt: unknown;
  updatedAt: unknown;
  entryCount: unknown;
}

const HISTORY_AND_RESUME = {port: 0, history: {enabled: true}, resume: {enabled: true}};
const HISTORY_ONLY = {port: 0, history: {enabled: true}};
const SUMMARY_KEYS = ['createdAt', 'entryCount', 'sessionId', 'updatedAt'];
const runningEngines: HalEngine[] = [];
const openSockets: WebSocket[] = [];
const silentLogger: Logger = {
  debug: () => undefined,
  info: () => undefined,
  warn: () => undefined,
  error: () => undefined,
};

beforeAll(() => {
  setLogger(silentLogger);
});

afterEach(async () => {
  for (const socket of openSockets.splice(0)) {
    socket.terminate();
  }
  for (const engine of runningEngines.splice(0)) {
    await drainServerClients(engine);
    await engine.stop();
  }
  setLogger(silentLogger);
});

afterAll(() => {
  setLogger();
});

it("lists the authenticated user's conversations newest first, pages by cursor, ignores a frame userId, and resumes a listed id", async () => {
  const {backing, baseMs} = seededUserStore();
  const storeCalls: RecordedListCall[] = [];
  const wsUrl = await bootEngine({session: observedListStore(backing, storeCalls), transport: HISTORY_AND_RESUME});

  const sessionClient = await openConnectedSocket(wsUrl);
  const firstList = await requestListAndSettle(sessionClient, {type: 'list_conversations', userId: 'u2'});
  const [headRow] = firstList.rows;
  const expectedCursor = {updatedAt: new Date(baseMs + 120_000).toISOString(), sessionId: 'conv-newer'};
  const nextCursor = headRow ? {updatedAt: headRow.updatedAt, sessionId: headRow.sessionId} : expectedCursor;
  const pagedRows = await requestPagedRows(sessionClient, nextCursor);
  const rejoined = await rejoinListedConversation(wsUrl, pagedRows);
  const liveSessionId = String(sessionClient.connected.sessionId ?? '');

  expect({
    replyType: firstList.replyType,
    trailingTypes: firstList.trailingTypes,
    listedIds: firstList.rows.map(row => row.sessionId),
    entryCounts: firstList.rows.map(row => row.entryCount),
    rowKeys: firstList.rawRows.map(row => Object.keys(row).sort()),
    isoTimes: areIsoRowTimestamps(firstList.rows),
    newestUpdatedAt: headRow?.updatedAt,
    pagedIds: pagedRows.map(row => row.sessionId),
    storeCalls,
    rejoined,
  }).toEqual({
    replyType: 'conversation_list',
    trailingTypes: ['pong'],
    listedIds: ['conv-newer', 'conv-older', liveSessionId],
    entryCounts: [2, 1, 0],
    rowKeys: [SUMMARY_KEYS, SUMMARY_KEYS, SUMMARY_KEYS],
    isoTimes: true,
    newestUpdatedAt: new Date(baseMs + 120_000).toISOString(),
    pagedIds: ['conv-older'],
    storeCalls: [
      {userId: 'u1', limit: undefined, before: undefined},
      {userId: 'u1', limit: 1, before: expectedCursor},
    ],
    rejoined: {
      resumed: true,
      sessionId: 'conv-older',
      replayedCount: 1,
    },
  });
});

it('validates list_conversations limits and composite cursors, rejecting malformed fields as INVALID_MESSAGE', async () => {
  const wireRejection = await probeWireLimitRejection();
  const cursorValue = {updatedAt: '2026-01-15T10:00:00.000Z', sessionId: 's1'};
  const bare = validateMessage({type: 'list_conversations'});
  const withExtraField = validateMessage({type: 'list_conversations', userId: 'u2'});
  const withCursor = validateMessage({
    type: 'list_conversations',
    limit: 200,
    before: cursorValue,
  });
  const badLimits = [0, 201, 1.5, '10'].map(limit => validateMessage({type: 'list_conversations', limit}));
  const bareBefore = validateMessage({type: 'list_conversations', before: 'not a date'});
  const badCursors = malformedCursorInputs().map(before => validateMessage({type: 'list_conversations', before}));

  expect({
    bare,
    withExtraField,
    withCursor,
    limitsNameField: badLimits.every(result => namesField(result, 'limit')),
    bareBeforeNamesField: namesField(bareBefore, 'before'),
    malformedCursorsNameField: badCursors.every(namesCursorField),
    wireRejection,
  }).toEqual({
    bare: {valid: true, data: {type: 'list_conversations'}},
    withExtraField: {valid: true, data: {type: 'list_conversations'}},
    withCursor: {
      valid: true,
      data: {
        type: 'list_conversations',
        limit: 200,
        before: cursorValue,
      },
    },
    limitsNameField: true,
    bareBeforeNamesField: true,
    malformedCursorsNameField: true,
    wireRejection: {
      code: 'INVALID_MESSAGE',
      frameTypes: ['error', 'pong'],
    },
  });
});

it('answers UNSUPPORTED when history is off or the store cannot list, and SERVER_ERROR without store detail when listing fails', async () => {
  const defaultOff = await probeDefaultHistoryOff();
  const minimalStoreOutcome = await probeStoreLackingListFor();
  const mongoOutcome = await probeMongoLackingFind();
  const rejectingOutcome = await probeRejectingListFor();
  const errorCodes: Record<string, string> = {...publicApi.ErrorCodes};

  expect({
    unsupportedCode: errorCodes.UNSUPPORTED,
    exportsStoreCannotList: 'StoreCannotList' in publicApi,
    connectedKeysWithHistoryOff: defaultOff.connectedKeys,
    whenHistoryOff: defaultOff.frames,
    warnedWithoutResume: minimalStoreOutcome.warnedWithoutResume,
    whenListForAbsent: minimalStoreOutcome.frames,
    whenStoreThrowsCannotList: mongoOutcome,
    whenListForRejects: rejectingOutcome,
  }).toEqual({
    unsupportedCode: 'UNSUPPORTED',
    exportsStoreCannotList: true,
    connectedKeysWithHistoryOff: ['examplePrompts', 'message', 'sessionId', 'type'],
    whenHistoryOff: [
      {type: 'error', code: 'UNSUPPORTED'},
      {type: 'pong', code: undefined},
    ],
    warnedWithoutResume: true,
    whenListForAbsent: [
      {type: 'error', code: 'UNSUPPORTED'},
      {type: 'pong', code: undefined},
    ],
    whenStoreThrowsCannotList: [
      {type: 'error', code: 'UNSUPPORTED'},
      {type: 'pong', code: undefined},
    ],
    whenListForRejects: {
      frames: [
        {type: 'error', code: 'SERVER_ERROR'},
        {type: 'pong', code: undefined},
      ],
      leakedStoreDetail: false,
      loggedSessionId: true,
      loggedUserContent: false,
    },
  });
});

it('answers list_conversations while a user_message turn is still streaming on the same session', async () => {
  const turnEntered = deferred();
  const releaseTurn = deferred();
  const backing = priorConversationStore();
  const wsUrl = await bootEngine({
    session: asyncListStore(backing),
    transport: HISTORY_AND_RESUME,
    orchestrator: {
      hooks: {
        beforeModelResponse: async (_session, systemPrompt) => {
          turnEntered.release();
          await releaseTurn.until;
          return systemPrompt;
        },
      },
    },
  });

  const socketClient = await openConnectedSocket(wsUrl);
  socketClient.send({type: 'user_message', content: 'hold the turn open'});
  await turnEntered.until;

  socketClient.send({type: 'list_conversations'});
  const replyWhileStreaming = await socketClient.nextListOrErrorWithin(500);
  releaseTurn.release();
  const remainingTurnFrames = await socketClient.framesThrough('stream_end');
  const listedRows = readConversationRows(replyWhileStreaming);

  expect({
    answeredBeforeTurnEnded: replyWhileStreaming.type,
    listedPriorConversation: listedRows.some(row => row.sessionId === 'conv-prior'),
    turnCompletedAfterward: remainingTurnFrames.some(frame => frame.type === 'stream_end'),
  }).toEqual({
    answeredBeforeTurnEnded: 'conversation_list',
    listedPriorConversation: true,
    turnCompletedAfterward: true,
  });
});

function seededUserStore(): {backing: InMemorySessionStore; baseMs: number} {
  const backing = new InMemorySessionStore();
  const older = backing.create('conv-older', 'u1');
  const [seedSummary] = backing.listFor('u1');
  const baseMs = seedSummary ? seedSummary.createdAt.getTime() : 0;
  older.entries.push({role: 'user', content: 'first question', timestamp: new Date(baseMs + 60_000).toISOString()});

  const newer = backing.create('conv-newer', 'u1');
  newer.entries.push(
    {role: 'user', content: 'second question', timestamp: new Date(baseMs + 110_000).toISOString()},
    {
      role: 'assistant',
      content: 'second answer',
      timestamp: new Date(baseMs + 120_000).toISOString(),
      isStreaming: false,
    }
  );
  const theirs = backing.create('conv-other', 'u2');
  theirs.entries.push({role: 'user', content: 'private', timestamp: new Date(baseMs + 180_000).toISOString()});
  return {backing, baseMs};
}

function observedListStore(backing: InMemorySessionStore, recorded: RecordedListCall[]): SessionStore {
  return {
    create: (sessionId, userId, options) => backing.create(sessionId, userId, options),
    get: sessionId => backing.get(sessionId),
    lookup: sessionId => backing.lookup(sessionId),
    delete: sessionId => backing.delete(sessionId),
    evict: sessionId => backing.evict(sessionId),
    count: () => backing.count(),
    clear: () => backing.clear(),
    latestFor: userId => backing.latestFor(userId),
    listFor: (userId, options?: SessionListOptions) => {
      recorded.push({userId, limit: options?.limit, before: options?.before});
      return backing.listFor(userId, options);
    },
  };
}

async function requestListAndSettle(
  socketClient: Awaited<ReturnType<typeof openConnectedSocket>>,
  payload: Record<string, unknown>
) {
  socketClient.send(payload);
  const reply = await socketClient.nextFrame();
  socketClient.send({type: 'ping', timestamp: 1});
  const trailing = await socketClient.framesThrough('pong');
  return {
    replyType: reply.type,
    trailingTypes: trailing.map(frame => frame.type),
    rawRows: readRawRows(reply),
    rows: readConversationRows(reply),
  };
}

async function requestPagedRows(
  socketClient: Awaited<ReturnType<typeof openConnectedSocket>>,
  cursor: {updatedAt: unknown; sessionId: unknown}
): Promise<WireConversationRow[]> {
  socketClient.send({type: 'list_conversations', limit: 1, before: cursor});
  const pagedReply = await socketClient.nextFrame();
  return readConversationRows(pagedReply);
}

async function rejoinListedConversation(wsUrl: string, pagedRows: WireConversationRow[]) {
  const [pagedHead] = pagedRows;
  if (typeof pagedHead?.sessionId !== 'string') return null;
  const resumedClient = await openConnectedSocket(`${wsUrl}?sessionId=${pagedHead.sessionId}`);
  resumedClient.send({type: 'ping', timestamp: 2});
  const resumedFrames = await resumedClient.framesThrough('pong');
  const replayedUpserts = resumedFrames.filter(frame => frame.type === 'entry_upsert');
  return {
    resumed: resumedClient.connected.resumed,
    sessionId: resumedClient.connected.sessionId,
    replayedCount: replayedUpserts.length,
  };
}

async function probeWireLimitRejection() {
  const wsUrl = await bootEngine({session: new InMemorySessionStore(), transport: HISTORY_AND_RESUME});
  const socketClient = await openConnectedSocket(wsUrl);
  socketClient.send({type: 'list_conversations', limit: 0});
  socketClient.send({type: 'ping', timestamp: 7});
  const wireFrames = await socketClient.framesThrough('pong');
  const [firstWireFrame] = wireFrames;
  return {
    code: firstWireFrame?.code,
    frameTypes: wireFrames.map(frame => frame.type),
  };
}

function malformedCursorInputs(): unknown[] {
  return [
    {updatedAt: 'not a date', sessionId: 's1'},
    {updatedAt: '2026-01-15T10:00:00.000Z'},
    {sessionId: 's1'},
    {updatedAt: '2026-01-15T10:00:00.000Z', sessionId: ''},
  ];
}

function namesField(result: ValidationResult, field: string): boolean {
  if (result.valid) return false;
  return result.error.includes(field);
}

function namesCursorField(result: ValidationResult): boolean {
  if (result.valid) return false;
  return ['before', 'updatedAt', 'sessionId'].some(field => result.error.includes(field));
}

async function probeDefaultHistoryOff() {
  const defaultUrl = await bootEngine({session: new InMemorySessionStore(), transport: {port: 0}});
  const {connected, frames} = await sendAndSettle(defaultUrl, {type: 'list_conversations'});
  return {
    connectedKeys: Object.keys(connected).sort(),
    frames: frameCodes(frames),
  };
}

async function probeStoreLackingListFor() {
  const startupWarnings: string[] = [];
  const warningLogger: Logger = {
    ...silentLogger,
    warn: (_category, message) => void startupWarnings.push(message),
  };
  const minimalUrl = await bootEngine({
    session: fiveMemberStore(new InMemorySessionStore()),
    transport: HISTORY_ONLY,
    logger: warningLogger,
  });
  const warnedWithoutResume = startupWarnings.length > 0;
  const {frames} = await sendAndSettle(minimalUrl, {type: 'list_conversations'});
  return {
    warnedWithoutResume,
    frames: frameCodes(frames),
  };
}

async function probeMongoLackingFind() {
  const mongoStore = new MongoSessionStore({collection: collectionLackingFind()});
  const mongoUrl = await bootEngine({session: mongoStore, transport: HISTORY_AND_RESUME});
  const {frames} = await sendAndSettle(mongoUrl, {type: 'list_conversations'});
  return frameCodes(frames);
}

async function probeRejectingListFor() {
  const errorEntries: Array<{message: string; fields: unknown}> = [];
  const errorLogger: Logger = {
    ...silentLogger,
    error: (_category, message, fields) => void errorEntries.push({message, fields}),
  };
  const failingUrl = await bootEngine({
    session: rejectingListStore(seededPrivateStore(), 'secret-database-detail'),
    transport: HISTORY_AND_RESUME,
    logger: errorLogger,
  });
  const {connected, frames} = await sendAndSettle(failingUrl, {type: 'list_conversations'});
  const sessionId = String(connected.sessionId ?? '');
  const [firstFrame] = frames;
  const serializedLogs = JSON.stringify(errorEntries);
  return {
    frames: frameCodes(frames),
    leakedStoreDetail: String(firstFrame?.message ?? '').includes('secret-database-detail'),
    loggedSessionId: sessionId.length > 0 && serializedLogs.includes(sessionId),
    loggedUserContent: serializedLogs.includes('confidential-prompt-text'),
  };
}

async function sendAndSettle(wsUrl: string, payload: Record<string, unknown>) {
  const socketClient = await openConnectedSocket(wsUrl);
  socketClient.send(payload);
  socketClient.send({type: 'ping', timestamp: 9});
  const frames = await socketClient.framesThrough('pong');
  return {connected: socketClient.connected, frames};
}

function frameCodes(frames: Record<string, unknown>[]): Array<{type: unknown; code: unknown}> {
  return frames.map(frame => ({type: frame.type, code: frame.code}));
}

function seededPrivateStore(): InMemorySessionStore {
  const seeded = new InMemorySessionStore();
  const privateSession = seeded.create('s-private', 'u1');
  privateSession.entries.push({
    role: 'user',
    content: 'confidential-prompt-text',
    timestamp: '2026-01-15T10:00:00.000Z',
  });
  return seeded;
}

function priorConversationStore(): InMemorySessionStore {
  const backing = new InMemorySessionStore();
  const prior = backing.create('conv-prior', 'u1');
  const [seedSummary] = backing.listFor('u1');
  const baseMs = seedSummary ? seedSummary.createdAt.getTime() : 0;
  prior.entries.push({role: 'user', content: 'earlier', timestamp: new Date(baseMs + 60_000).toISOString()});
  return backing;
}

function asyncListStore(backing: InMemorySessionStore): SessionStore {
  return {
    ...fiveMemberStore(backing),
    listFor: async (userId, options) => backing.listFor(userId, options),
  };
}

function rejectingListStore(backing: InMemorySessionStore, reason: string): SessionStore {
  return {
    ...fiveMemberStore(backing),
    listFor: () => Promise.reject(new Error(reason)),
  };
}

function fiveMemberStore(backing: InMemorySessionStore): SessionStore {
  return {
    create: (sessionId, userId, options) => backing.create(sessionId, userId, options),
    get: sessionId => backing.get(sessionId),
    delete: sessionId => backing.delete(sessionId),
    count: () => backing.count(),
    clear: () => backing.clear(),
  };
}

function collectionLackingFind(): CollectionLike<MongoSessionDocument> {
  return {
    findOne: () => Promise.resolve(null),
    updateOne: () => Promise.resolve(undefined),
    deleteOne: () => Promise.resolve({deletedCount: 0}),
    deleteMany: () => Promise.resolve({deletedCount: 0}),
    countDocuments: () => Promise.resolve(0),
  };
}

async function bootEngine(overrides: Partial<HalEngineConfig>): Promise<string> {
  const wsAuth: WsAuthenticator = async () => ({id: 'u1'});
  const provider: HalEngineConfig['provider'] = {type: 'mock'};
  const engine = createHalEngine({
    provider,
    prompt: {identity: 'Acceptance assistant.'},
    auth: {ws: wsAuth},
    ...overrides,
  });
  runningEngines.push(engine);
  await engine.start(0);
  const address = engine.server.address();
  const port = typeof address === 'object' && address !== null ? address.port : -1;
  return `ws://127.0.0.1:${port}/hal/ws`;
}

async function openConnectedSocket(url: string) {
  const socket = new WebSocket(url, [HAL_WS_SUBPROTOCOL, 'test-token']);
  openSockets.push(socket);
  const reader = createSocketReader(socket);
  const connected = await reader.nextFrame();
  return {
    connected,
    send: (payload: Record<string, unknown>) => socket.send(JSON.stringify(payload)),
    nextFrame: reader.nextFrame,
    framesThrough: reader.framesThrough,
    nextListOrErrorWithin: reader.nextListOrErrorWithin,
  };
}

function createSocketReader(socket: WebSocket) {
  const queue: Record<string, unknown>[] = [];
  const waiters: Array<(frame: Record<string, unknown>) => void> = [];

  socket.on('message', raw => {
    const parsed = parseJsonFrame(raw);
    const waiter = waiters.shift();
    if (waiter) {
      waiter(parsed);
      return;
    }
    queue.push(parsed);
  });

  const takeFrame = (): {promise: Promise<Record<string, unknown>>; cancel: () => void} => {
    const buffered = queue.shift();
    if (buffered) return {promise: Promise.resolve(buffered), cancel: () => undefined};
    let waiter: ((frame: Record<string, unknown>) => void) | undefined;
    const promise = new Promise<Record<string, unknown>>(resolve => {
      waiter = resolve;
      waiters.push(resolve);
    });
    const cancel = (): void => {
      const index = waiter ? waiters.indexOf(waiter) : -1;
      if (index >= 0) waiters.splice(index, 1);
    };
    return {promise, cancel};
  };

  const nextFrame = (): Promise<Record<string, unknown>> => takeFrame().promise;

  const framesThrough = async (terminalType: string): Promise<Record<string, unknown>[]> => {
    const collected: Record<string, unknown>[] = [];
    while (collected.at(-1)?.type !== terminalType) {
      collected.push(await nextFrame());
    }
    return collected;
  };

  const nextListOrErrorWithin = async (timeoutMs: number): Promise<Record<string, unknown>> => {
    let timer: ReturnType<typeof setTimeout> | undefined;
    let stopped = false;
    let cancelPending = (): void => undefined;
    const timeoutPromise = new Promise<Record<string, unknown>>(resolve => {
      timer = setTimeout(() => {
        stopped = true;
        cancelPending();
        resolve({type: 'timed_out_behind_lock'});
      }, timeoutMs);
    });
    const matchingFrame = async (): Promise<Record<string, unknown>> => {
      while (!stopped && socket.readyState === WebSocket.OPEN) {
        const pending = takeFrame();
        cancelPending = pending.cancel;
        const frame = await pending.promise;
        if (frame.type === 'conversation_list' || frame.type === 'error') return frame;
      }
      return {type: 'socket_closed'};
    };
    const winner = await Promise.race([matchingFrame(), timeoutPromise]);
    if (timer !== undefined) clearTimeout(timer);
    return winner;
  };

  return {nextFrame, framesThrough, nextListOrErrorWithin};
}

function readConversationRows(frame: Record<string, unknown>): WireConversationRow[] {
  return readRawRows(frame).map(row => ({
    sessionId: row.sessionId,
    createdAt: row.createdAt,
    updatedAt: row.updatedAt,
    entryCount: row.entryCount,
  }));
}

function readRawRows(frame: Record<string, unknown>): Record<string, unknown>[] {
  const {conversations} = frame;
  if (!Array.isArray(conversations)) return [];
  return conversations.filter(isRecord);
}

function parseJsonFrame(raw: unknown): Record<string, unknown> {
  const parsed: unknown = JSON.parse(String(raw));
  if (isRecord(parsed)) return parsed;
  throw new Error('Expected JSON object frame');
}

function isRecord(candidate: unknown): candidate is Record<string, unknown> {
  return typeof candidate === 'object' && candidate !== null && !Array.isArray(candidate);
}

async function drainServerClients(engine: HalEngine): Promise<void> {
  const {clients} = engine.wss;
  for (let i = 0; i < 50 && clients.size > 0; i++) {
    await new Promise<void>(resolve => setTimeout(resolve, 5));
  }
}

function areIsoRowTimestamps(rows: WireConversationRow[]): boolean {
  if (rows.length === 0) return false;
  return rows.every(row => isIsoTimestamp(row.createdAt) && isIsoTimestamp(row.updatedAt));
}

function isIsoTimestamp(candidate: unknown): boolean {
  if (typeof candidate !== 'string') return false;
  const parsedMs = Date.parse(candidate);
  return Number.isFinite(parsedMs) && new Date(parsedMs).toISOString() === candidate;
}
